export function resolveCostRequirementContext(requirement:CostRequirement,selectedCosts:readonly CostItem[],interval:ClosedDateInterval,context?:ScopeMatchContext):CostRequirementContextResult{
const period=resolveCostRequirementPeriod(requirement,selectedCosts,interval);
if(period.status==='unavailable'){
return{status:'unavailable',stage:'period',period,scopeMatch:null,costAdmission:'not-evaluated',costItemId:period.costItemId,reason:period.reason};
}
const scopeMatch=matchParameterScope(requirement.provenance.scope,context);
if(scopeMatch.status!=='scope-matched'){
return{status:'unavailable',stage:'scope',period,scopeMatch,reason:scopeMatch.status==='invalid-scope'?`escopo do requerimento inválido: ${scopeMatch.reason}`:`falta contexto para escopo do requerimento: ${scopeMatch.field} ${scopeMatch.reason}`,costItemId:null};
}
if(period.status==='declared-not-applicable'){
const check=Object.freeze({subject:'requirement',subjectId:period.requirementId,match:scopeMatch});
return{status:'declared-not-applicable',period,scopeChecks:Object.freeze([check]),costAdmission:'not-evaluated'};
}
const scopeChecks:CostScopeCheck[]=[];
for(const id of period.costItemIds){
const item=selectedCosts.find(c=>c.id===id);
if(!item){
return{status:'unavailable',stage:'selection',period,scopeMatch:null,reason:`custo selecionado não encontrado: ${id}`,costItemId:id};
}
const itemScope=matchParameterScope(item.provenance.scope,context);
if(itemScope.status!=='scope-matched'){
return{status:'unavailable',stage:'scope',period,scopeMatch:itemScope,reason:`escopo do custo ${id} não corresponde: ${itemScope.status==='invalid-scope'?itemScope.reason:`falta ${itemScope.field}: ${itemScope.reason}`}`,costItemId:id};
}
scopeChecks.push(Object.freeze({subject:'cost-item',subjectId:id,match:itemScope}));
}
return{status:'context-checked',period:period as Extract<CostRequirementPeriodResult,{status:'period-covered'}>,scopeChecks:Object.freeze(scopeChecks),costAdmission:'not-evaluated'};
}
